// Format Google Drive file data for email display
const response = $input.first().json;

// Check if we have a valid response with files
if (!response || !response.files || !Array.isArray(response.files)) {
  return [{ json: { files: [], hasChanges: false } }];
}

const files = response.files;

// Format file data with HTML
const formattedFiles = files.map(file => ({
  name: file.name || 'Unnamed File',
  link: file.webViewLink || file.webContentLink || '#',
  modifiedTime: file.modifiedTime ? new Date(file.modifiedTime).toLocaleString() : 'Unknown',
  size: file.size ? `${(file.size / 1024).toFixed(2)} KB` : 'N/A',
  mimeType: file.mimeType || 'Unknown'
}));

// Build HTML email body
const emailBody = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <h2 style="color: #1a73e8; border-bottom: 2px solid #1a73e8; padding-bottom: 10px;">
    📁 Google Drive Activity Report
  </h2>
  <p style="font-size: 16px; color: #333;">
    <strong>${files.length}</strong> file(s) were modified in your Google Drive in the last hour.
  </p>
  <div style="background-color: #f8f9fa; padding: 15px; border-radius: 5px;">
    ${formattedFiles.map(file => `
      <div style="margin-bottom: 15px; padding: 10px; background-color: white; border-left: 4px solid #1a73e8;">
        <div style="font-size: 16px; font-weight: bold; margin-bottom: 5px;">
          <a href="${file.link}" style="color: #1a73e8; text-decoration: none;">${file.name}</a>
        </div>
        <div style="font-size: 13px; color: #666;">
          📅 Modified: ${file.modifiedTime}<br>
          📊 Size: ${file.size}<br>
          📄 Type: ${file.mimeType}
        </div>
      </div>
    `).join('')}
  </div>
  <p style="font-size: 12px; color: #999; margin-top: 20px; border-top: 1px solid #ddd; padding-top: 10px;">
    This is an automated notification from your Google Drive monitoring workflow.
  </p>
</div>
`;

return [{
  json: {
    files: formattedFiles,
    fileCount: files.length,
    hasChanges: files.length > 0,
    emailBody: emailBody,
    emailSubject: `📁 Google Drive Update: ${files.length} file(s) changed`
  }
}];
